const runtime = createRequire(path.join(runtimeRoot, 'package.json'));
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pd-r7-retry-'));
fs.mkdirSync(path.join(home, 'tmux'));
const env = load('./test/test-env').sanitizeTestEnv({ PATH: process.env.PATH, HOME: home });
for (const key of Object.keys(process.env)) delete process.env[key];
Object.assign(process.env, env, { PI_DISH_TERMINAL: '1', TMUX_TMPDIR: path.join(home, 'tmux') });
const trace = { terminalConstructions: 0, attempts: [] };
const terminal = runtime('./lib/terminal-handlers');
const createTerminal = terminal.createTerminalHandlers;
terminal.createTerminalHandlers = function (...args) { trace.terminalConstructions++; return createTerminal.apply(this, args); };
const listen = net.Server.prototype.listen;
let replacement;
let bindResolve;
const bound = new Promise(resolve => { bindResolve = resolve; });
net.Server.prototype.listen = function (...args) {
  if (!(this instanceof http.Server)) return listen.apply(this, args);
  trace.attempts.push({ at: performance.now(), upgradeListeners: this.listenerCount('upgrade'), terminalConstructions: trace.terminalConstructions });
  if (trace.attempts.length === 1) {
    process.nextTick(() => this.emit('error', Object.assign(new Error('isolated interface unavailable'), { code: 'EADDRNOTAVAIL' })));
    return this;
  }
  replacement = this;
