  return new Promise((resolve, reject) => {
    const req = http.request(base + route, { headers: { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': 'dGhlIHNhbXBsZSBub25jZQ==' } });
    req.on('response', response => { response.resume(); resolve(response.statusCode); });
    req.on('upgrade', (_response, socket) => { socket.destroy(); resolve(101); });
    req.on('error', reject);
    req.end();
  });
}
