  try {
    await bound;
    const elapsed = trace.attempts[1].at - trace.attempts[0].at;
    assert.ok(elapsed >= 14900, `retry interval shortened: ${elapsed}`);
    assert.equal(initial.listening, false);
    assert.notEqual(initial, replacement);
    assert.equal(trace.terminalConstructions, 1);
    const base = `http://127.0.0.1:${replacement.address().port}`;
    if (phase === 'final') {
      assert.equal(ready, base);
      for (const attempt of trace.attempts) {
        assert.equal(attempt.upgradeListeners, 1);
        assert.equal(attempt.terminalConstructions, 1);
      }
    }
    assert.equal((await fetch(base + '/api/host')).status, 200);
