    assert.equal(await upgrade(base, '/hosts/missing/api/sessions/missing/terminal'), 404);
    const result = { result: 'PASS', phase, closeCode, retryMilliseconds: elapsed, ready, trace, checks: ['initial close preserves pending retry', 'replacement HTTP and local/fleet WS dispatch', 'native initial export identity retained'] };
    fs.writeFileSync(`/tmp/pi-dish-r7-retry-${phase}.json`, JSON.stringify(result, null, 2));
    console.log(JSON.stringify(result, null, 2));
  } finally {
    clearTimeout(timer);
    net.Server.prototype.listen = listen;
    if (replacement?.listening) await new Promise(resolve => replacement.close(resolve));
    fs.rmSync(home, { recursive: true, force: true });
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

